BEGIN;
SELECT plan(20);
SELECT has_table('public','communication_webhook_events','Twilio webhook inbox exists');
SELECT has_table('public','affiliate_webhook_events','affiliate webhook inbox exists');
SELECT has_table('public','twilio_sms_requests','outbound SMS request audit exists');
SELECT has_table('public','twilio_message_status_events','SMS delivery callback audit exists');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.communication_webhook_events'::regclass),'Twilio inbox has RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.affiliate_webhook_events'::regclass),'affiliate inbox has RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.twilio_sms_requests'::regclass),'SMS request audit has RLS enabled');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.twilio_message_status_events'::regclass),'SMS status audit has RLS enabled');
SELECT ok(NOT has_table_privilege('anon','public.communication_webhook_events','SELECT'),'anon cannot read Twilio inbox');
SELECT ok(NOT has_table_privilege('authenticated','public.communication_webhook_events','SELECT'),'authenticated cannot read Twilio inbox');
SELECT ok(NOT has_table_privilege('anon','public.affiliate_webhook_events','SELECT'),'anon cannot read affiliate inbox');
SELECT ok(NOT has_table_privilege('authenticated','public.affiliate_webhook_events','SELECT'),'authenticated cannot read affiliate inbox');
SELECT ok(NOT has_table_privilege('anon','public.twilio_sms_requests','SELECT'),'anon cannot read SMS request audit');
SELECT ok(NOT has_table_privilege('authenticated','public.twilio_sms_requests','SELECT'),'authenticated cannot read SMS request audit');
SELECT ok(NOT has_table_privilege('anon','public.twilio_message_status_events','SELECT'),'anon cannot read SMS status audit');
SELECT ok(NOT has_table_privilege('authenticated','public.twilio_message_status_events','SELECT'),'authenticated cannot read SMS status audit');
SELECT ok(has_table_privilege('service_role','public.communication_webhook_events','INSERT'),'service role can persist Twilio events');
SELECT ok(has_table_privilege('service_role','public.affiliate_webhook_events','INSERT'),'service role can persist affiliate events');
SELECT has_index('public','twilio_sms_requests_user_created_idx','SMS requests have a per-user lookup index');
SELECT has_index('public','twilio_message_status_events_sid_received_idx','SMS status events have a SID/time index');
SELECT * FROM finish();
ROLLBACK;
